LOCK TABLES `chapters` WRITE;
/*!40000 ALTER TABLE `chapters` DISABLE KEYS */;
INSERT INTO `chapters` VALUES (1,'Form 4','Chapter 1','Quadratic Functions and Equations in One Variable','Fungsi dan Persamaan Kuadratik dalam Satu Pemboleh Ubah','Identifying and solving equations with a power of two to find roots.','Mengenal pasti dan menyelesaikan persamaan kuasa dua untuk mencari punca.'),(2,'Form 4','Chapter 2','Number Bases','Asas Nombor','Understanding how to represent and calculate numbers in bases other than ten.','Memahami cara mewakilkan dan mengira nombor dalam asas selain sepuluh.'),(3,'Form 4','Chapter 3','Logical Reasoning','Penaakulan Logik','Using logic to determine the truth of statements and building valid arguments.','Menggunakan logik untuk menentukan kebenaran pernyataan dan membina hujah yang sah.'),(4,'Form 4','Chapter 4','Operations on Sets','Operasi Set','Learning the relationships between different groups of data using intersections and unions.','Mempelajari hubungan antara kumpulan data menggunakan persilangan dan kesatuan.'),(5,'Form 4','Chapter 5','Network in Graph Theory','Rangkaian dalam Teori Graf','Representing complex connections using points and lines to solve networking problems.','Mewakilkan hubungan kompleks menggunakan titik dan garis untuk menyelesaikan masalah rangkaian.'),(6,'Form 4','Chapter 6','Linear Inequalities in Two Variables','Ketaksamaan Linear dalam Dua Pemboleh Ubah','Representing and shading regions on a graph that satisfy specific range conditions.','Mewakilkan dan melorek rantau pada graf yang memenuhi syarat julat tertentu.'),(7,'Form 4','Chapter 7','Graphs of Motion','Graf Gerakan','Analyzing distance-time and speed-time graphs to understand physical movement.','Menganalisis graf jarak-masa dan laju-masa untuk memahami gerakan fizikal.'),(8,'Form 4','Chapter 8','Measures of Dispersion for Ungrouped Data','Sukatan Serakan Data Tak Terkumpul','Measuring how spread out data is using range, variance, and standard deviation.','Mengukur sejauh mana data tersebar menggunakan julat, varians, dan sisihan piawai.'),(9,'Form 4','Chapter 9','Probability of Combined Events','Kebarangkalian Peristiwa Bergabung','Calculating the likelihood of two or more events happening together.','Mengira kemungkinan dua atau lebih peristiwa berlaku secara bersama.'),(10,'Form 4','Chapter 10','Consumer Mathematics: Financial Management','Matematik Pengguna: Pengurusan Kewangan','Planning budgets and managing cash flow to achieve financial goals.','Merancang bajet dan mengurus aliran tunai untuk mencapai matlamat kewangan.'),(11,'Form 5','Chapter 1','Variation','Ubahan','Studying how one variable changes in relation to another directly or inversely.','Mengkaji bagaimana satu pemboleh ubah berubah berhubung dengan yang lain secara langsung atau songsang.'),(12,'Form 5','Chapter 2','Matrices','Matriks','Organizing numbers into rows and columns to solve linear equations efficiently.','Menyusun nombor dalam baris dan lajur untuk menyelesaikan persamaan linear dengan cekap.'),(13,'Form 5','Chapter 3','Consumer Mathematics: Insurance','Matematik Pengguna: Insurans','Understanding the types of insurance and how to calculate premiums and compensation.','Memahami jenis insurans dan cara mengira premium serta pampasan.'),(14,'Form 5','Chapter 4','Consumer Mathematics: Taxation','Matematik Pengguna: Percukaian','Learning about different types of taxes and how to calculate income tax.','Mempelajari pelbagai jenis cukai dan cara mengira cukai pendapatan.'),(15,'Form 5','Chapter 5','Congruency, Enlargement and Combined Transformations','Kekongruenan, Pembesaran dan Gabungan Transformasi','Exploring how shapes change size or position while maintaining certain properties.','Meneroka bagaimana bentuk berubah saiz atau kedudukan sambil mengekalkan ciri tertentu.'),(16,'Form 5','Chapter 6','Ratios and Graphs of Trigonometric Functions','Nisbah dan Graf Fungsi Trigonometri','Analyzing the behavior of sine, cosine, and tangent functions on a graph.','Menganalisis sifat fungsi sinus, kosinus, dan tangen pada graf.'),(17,'Form 5','Chapter 7','Measures of Dispersion for Grouped Data','Sukatan Serakan Data Terkumpul','Calculating the spread of data that has been organized into intervals or classes.','Mengira serakan data yang telah disusun dalam selang atau kelas.'),(18,'Form 5','Chapter 8','Mathematical Modeling','Pemodelan Matematik','Using mathematical formulas to represent and solve real-world complex problems.','Menggunakan formula matematik untuk mewakilkan dan menyelesaikan masalah dunia sebenar yang kompleks.');
/*!40000 ALTER TABLE `chapters` ENABLE KEYS */;
UNLOCK TABLES;

