CREATE TABLE `questions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `paper_id` int DEFAULT NULL,
  `question_no` varchar(10) DEFAULT NULL,
  `part` varchar(10) DEFAULT NULL,
  `subpart` varchar(10) DEFAULT NULL,
  `sub_subpart` varchar(10) DEFAULT NULL,
  `question_type` varchar(50) DEFAULT NULL,
  `topic` varchar(100) DEFAULT NULL,
  `subtopic` varchar(100) DEFAULT NULL,
  `form` varchar(20) DEFAULT NULL,
  `chapter` varchar(100) DEFAULT NULL,
  `instructions_en` json DEFAULT NULL,
  `instructions_ms` json DEFAULT NULL,
  `sequence` json DEFAULT NULL,
  `equations` json DEFAULT NULL,
  `expressions` json DEFAULT NULL,
  `variables` json DEFAULT NULL,
  `given_values` json DEFAULT NULL,
  `table_data` json DEFAULT NULL,
  `constraints` json DEFAULT NULL,
  `options` json DEFAULT NULL,
  `target` text,
  `has_diagram` tinyint(1) DEFAULT NULL,
  `diagram_type` varchar(255) DEFAULT NULL,
  `difficulty` varchar(20) DEFAULT NULL,
  `marks` int DEFAULT '0',
  `visual_semantic_summary` text,
  `raw_json` json DEFAULT NULL,
  `image_path` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `group_id` varchar(100) DEFAULT NULL,
  `verified_form` varchar(50) DEFAULT NULL,
  `verified_chapter` varchar(200) DEFAULT NULL,
  `classification_status` varchar(50) DEFAULT 'unclassified',
  `classification_confidence` decimal(4,2) DEFAULT '0.00',
  `difficulty_level` int DEFAULT '3',
  `group_difficulty_level` int DEFAULT '3',
  `group_chapter` varchar(200) DEFAULT NULL,
  `group_form` varchar(50) DEFAULT NULL,
  `exercise_stage_id` varchar(120) DEFAULT NULL,
  `stage_index` int DEFAULT '1',
  `unlock_after_stage_id` varchar(120) DEFAULT NULL,
  `display_marks` decimal(5,2) DEFAULT '0.00',
  `marks_source` varchar(50) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `paper_id` (`paper_id`),
  CONSTRAINT `questions_ibfk_1` FOREIGN KEY (`paper_id`) REFERENCES `papers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1160 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
