INSERT INTO `review_variants` VALUES (17,17766,716355,'question','question:612',NULL,NULL,612,'k1_mcq_variant','bm','{\"options\": [{\"label\": \"A\", \"text_en\": \"4\", \"text_ms\": \"4\", \"image_path\": \"\"}, {\"label\": \"B\", \"text_en\": \"2\", \"text_ms\": \"2\", \"image_path\": \"\"}, {\"label\": \"C\", \"text_en\": \"-2\", \"text_ms\": \"-2\", \"image_path\": \"\"}, {\"label\": \"D\", \"text_en\": \"-4\", \"text_ms\": \"-4\", \"image_path\": \"\"}], \"sequence\": [\"text_0\", \"image_0\", \"text_1\"], \"image_path\": \"https://res.cloudinary.com/dn04h9kz9/image/upload/v1778665517/b8c0a146-ba02-42d3-b73b-f0cdb1dac5c2.png\", \"image_urls\": [\"https://res.cloudinary.com/dn04h9kz9/image/upload/v1778665517/b8c0a146-ba02-42d3-b73b-f0cdb1dac5c2.png\"], \"table_data\": {}, \"has_diagram\": 1, \"diagram_type\": \"graph\", \"given_values\": {}, \"display_marks\": 1, \"instructions_en\": [\"Diagram 12 shows a graph function of y = x² - 4\", \"Find the value of the x-intercept.\"], \"instructions_ms\": [\"Rajah 12 menunjukkan graf fungsi bagi y = x² - 4\", \"Cari nilai pintasan-x.\"]}','{\"max_score\": 1, \"final_answer\": \"B\", \"explanation_bm\": \"Bagi y = x² - 4, pintasan-x berlaku apabila y = 0. Maka x² - 4 = 0, jadi x = ±2. Graf menunjukkan pintasan-x positif ialah 2, sepadan dengan pilihan B.\", \"explanation_en\": \"For y = x² - 4, the x-intercepts occur when y = 0. So x² - 4 = 0, giving x = ±2. The graph shows the positive x-intercept is 2, which matches option B.\"}',0,0,NULL,NULL,'queued','2026-05-18 07:00:05','2026-05-18 07:00:05',NULL),(18,17766,716356,'question','question:395',NULL,NULL,395,'k1_mcq_variant','english','{\"options\": [{\"label\": \"A\", \"text_en\": \"a = 4, c = -3\", \"text_ms\": \"a = 4, c = -3\", \"image_path\": \"\"}, {\"label\": \"B\", \"text_en\": \"a = 4, c = -6\", \"text_ms\": \"a = 4, c = -6\", \"image_path\": \"\"}, {\"label\": \"C\", \"text_en\": \"a = 7, c = -3\", \"text_ms\": \"a = 7, c = -3\", \"image_path\": \"\"}, {\"lab